-- Synthetic fixture for the RLS proofs. Fixed UUIDs so the tests can name actors.
-- Two clubs (A, B). Club A has two teams, two families, two coaches and a
-- player with their own login. Everything is invented.

-- clean up any earlier run
delete from public.clubs where id in ('c0000000-0000-4000-8000-000000000001', 'c0000000-0000-4000-8000-000000000002');
delete from public.platform_users where user_id = 'a0000000-0000-4000-8000-000000000099';
delete from auth.users where email like '%@rls.test';

select id, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', email,
       extensions.crypt('Passw0rd!rls', extensions.gen_salt('bf')), now(),
       '{"provider":"email","providers":["email"]}'::jsonb, '{}'::jsonb, now(), now()
from (values
  ('a0000000-0000-4000-8000-000000000001'::uuid, 'admin-a@rls.test'),
  ('a0000000-0000-4000-8000-000000000002', 'coach-a@rls.test'),
  ('a0000000-0000-4000-8000-000000000003', 'coach-a2@rls.test'),
  ('a0000000-0000-4000-8000-000000000004', 'parent-a1@rls.test'),
  ('a0000000-0000-4000-8000-000000000005', 'parent-a2@rls.test'),
  ('a0000000-0000-4000-8000-000000000006', 'player-a1@rls.test'),
  ('a0000000-0000-4000-8000-000000000011', 'admin-b@rls.test'),
  ('a0000000-0000-4000-8000-000000000012', 'coach-b@rls.test'),
  ('a0000000-0000-4000-8000-000000000013', 'parent-b@rls.test'),
  ('a0000000-0000-4000-8000-000000000077', 'newbie@rls.test'),
  ('a0000000-0000-4000-8000-000000000099', 'owner@rls.test')
) as u(id, email);











-- people: staff (coaches with logins), guardians (with logins), players



-- coach A coaches team 1 (child one + child two); coach A2 coaches team 2 (child three)
















